import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`house-flip-analysis`,heroTitle:`Analyze your next house flip in minutes`,heroSubtitle:`Perplexity Computer reviews the listing, estimates renovation scope, checks comps, and builds a flip model with a buy/pass recommendation.`,inputUrlCta:`Analyze this flip`,inputUrlPlaceholder:`www.zillow.com...`,inputUrlPrefill:`Go to {url} and analyze this property as a house flip. 1) Extract listing details, photos, price history, taxes, square footage, beds, baths, lot size, and neighborhood context. 2) Estimate renovation scope and likely repair budget from listing details and visible condition. 3) Find comparable renovated sales and active listings nearby. 4) Build a flip model with purchase price, closing costs, renovation budget, holding costs, selling costs, after-repair value, expected profit, and margin of safety. 5) Deliver a buy/pass recommendation with risks and next diligence steps.`,heroOverlaySteps:[`Pulling listing details, photos, price history, taxes, and neighborhood context`,`Estimating repair scope, renovation budget, and holding costs`,`Finding renovated comps and active listings near the property`,`Flip model, risks, and buy/pass recommendation ready to review`],generatingSteps:[`Visiting {url} to extract listing details, property history, and condition signals`,`Designing an agent to estimate renovation scope and repair budget ranges`,`Configuring comparable sale research and after-repair value calculations`,`Setting up the flip model with profit, margin of safety, and diligence steps`],featureSectionTitle:`From listing to flip decision`,featureCardTitles:[`Connects property and market data`,`Numbers you can underwrite`],featureCardDescriptions:[`Computer separates listing review, rehab estimation, comp research, and underwriting so each step gets handled by the right model.`,`Zillow, Redfin, Realtor.com, county records, Google Sheets, and Drive can all feed one workflow for faster deal screening.`,`Repair budget ranges. ARV comps. Profit model. Risk checklist. Computer delivers a complete first-pass flip analysis.`],capabilitySectionTitle:`Your flip analyst, on autopilot`,capabilitySectionSubtitle:`Paste a property listing and get back a renovation-aware flip model.`,capabilityCards:[{title:`Listing Review`,description:`Computer can pull price history, property specs, photos, taxes, and neighborhood context from a single listing link.`},{title:`Repair Budget Estimate`,description:`Computer can estimate renovation scope and budget ranges from listing details, visible condition, and common local costs.`},{title:`ARV Comp Analysis`,description:`Computer can find renovated comparable sales and active listings nearby to support an after-repair value range.`},{title:`Connect Your Tools`,description:`Computer can organize underwriting in Sheets, Docs, Drive, and your deal tracker so partners can review it quickly.`},{title:`Remember Your Buy Box`,description:`Computer can remember target profit, margin, neighborhood, renovation scope, and risk tolerance for future analyses.`},{title:`New Deal Alerts`,description:`Computer can monitor listings that match your buy box and flag properties worth deeper flip diligence.`}]});export{t as default};
